const daysAgo = (days: number) => new Date(nowMs - days * 24 * 60 * 60 * 1000);
const daysAhead = (days: number) => new Date(nowMs + days * 24 * 60 * 60 * 1000);

// --------------------------------------------------------------- demo documents
const DOCUMENTS_DIR = path.join(process.cwd(), "data", "private-documents");
mkdirSync(DOCUMENTS_DIR, { recursive: true });

function minimalPdf(label: string): string {
  const body = `BT /F1 12 Tf 72 780 Td (AngkorEV demo document) Tj 0 -20 Td (${label}) Tj 0 -20 Td (Sample only - not a real registration document) Tj ET`;
  const objects = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>",
    `<< /Length ${body.length} >>\nstream\n${body}\nendstream`,
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
  ];
  let pdf = "%PDF-1.4\n";
  objects.forEach((obj, index) => {
    pdf += `${index + 1} 0 obj\n${obj}\nendobj\n`;
  });
  pdf += "trailer\n<< /Root 1 0 R >>\n%%EOF\n";
  return pdf;
}

function seedDocumentFile(fileName: string, label: string) {
  const full = path.join(DOCUMENTS_DIR, fileName);
  if (!existsSync(full)) writeFileSync(full, minimalPdf(label), "utf8");
}

